// The project's own pack: the cross-tier delivery contract of Shouts & Whispers
// — the invariants that hold between the Flutter client and the Cloud Functions
// and that no canon pack owns (flutter/firebase/node cover their platforms,
// spec-driven-product and executable-requirements cover the loop and the spec
// harness; none of them knows that a presence geohash written by one tier is
// range-queried by the other).
//
// A local pack is declared by hand, never fingerprinted or seeded, so `detect`
// and `marker` stay null; it activates from the `local/shouts-and-whispers`
// token in .claudinite-checks.json.
import crossTierConstants from './cross-tier-constants.mjs';
import crossTierConstantCoverage from './cross-tier-constant-coverage.mjs';
import geohashPrecisionParity from './geohash-precision-parity.mjs';
import geohashVectorParity from './geohash-vector-parity.mjs';

export default {
  id: 'shouts-and-whispers',
  ruleRoutingGuidance: {
    belongs: 'the cross-tier delivery contract between the Flutter client and Cloud Functions — shared constants, geohash parity',
    excludes: 'single-platform concerns — those are flutter, firebase and node',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [
    crossTierConstants,
    crossTierConstantCoverage,
    geohashPrecisionParity,
    geohashVectorParity,
  ],
};

1	// RULES.md §"One table, two copies": the delivery constants that both tiers must
2	// agree on live in docs/DESIGN.md §10 and are copied into the server's
3	// constants.ts and the client's config.dart — files that cannot share an import
4	// (TypeScript and Dart). This guard compares the copies BY NAME PAIR, so a value
5	// changed on one side and forgotten on the other is a finding rather than a
6	// production bug that only shows up as messages silently not delivered.
7	//
8	// Why not the canon `shared-constants` guard: that one counts occurrences of a
9	// declared literal per file. Here the literals collide as substrings ("150" is
10	// inside "1500"), the paired identifiers differ by language convention
11	// (WHISPER_RADIUS_M / whisperRadiusM), and a value only stays guarded as long as
12	// someone remembers to declare it. Pairing the declarations by name needs no
13	// per-value upkeep and reads the same table docs/DESIGN.md §10 publishes.
14	//
15	// Dependency-free by design (a local pack's checks must load without the shared
16	// mount): it builds plain finding objects instead of importing the engine helper.
17	
18	const SERVER_FILE = 'firebase/functions/src/constants.ts';
19	const CLIENT_FILE = 'app/lib/config.dart';
20	const DESIGN_FILE = 'docs/DESIGN.md';
21	
22	// The cross-tier constants: server name ↔ client name. A server-only constant
23	// (PRESENCE_TTL_MS, SEND_COOLDOWN_MS) or a client-only one (the heartbeat
24	// cadence) has no pair and is deliberately absent — only values BOTH tiers
25	// carry can drift apart.
26	const PAIRS = [
27	  { server: 'WHISPER_RADIUS_M', client: 'whisperRadiusM' },
28	  { server: 'SHOUT_RADIUS_M', client: 'shoutRadiusM' },
29	  { server: 'MAX_TEXT_LEN', client: 'maxTextLen' },
30	  { server: 'REGION', client: 'functionsRegion' },
31	];
32	
33	const rule = {
34	  id: 'shouts-and-whispers/cross-tier-constants',
35	  severity: 'blocking',
36	  description: 'The delivery constants the client and the Cloud Functions both carry hold the same value, and match docs/DESIGN.md §10',
37	  doc: '.claudinite/local/packs/shouts-and-whispers/RULES.md',
38	  why: 'the two tiers cannot share an import, so a radius or limit changed on one side and forgotten on the other compiles, passes every test, and only shows up as messages quietly reaching the wrong people',
39	
40	  run(ctx) {
41	    const out = [];
42	    const say = (file, what, fix) => out.push({
43	      rule: rule.id, severity: rule.severity, file, line: null,
44	      what, why: rule.why, fix, doc: rule.doc,
45	    });
46	
47	    const serverText = ctx.read(SERVER_FILE);
48	    const clientText = ctx.read(CLIENT_FILE);
49	    const designText = ctx.read(DESIGN_FILE);
50	
51	    // Staleness guard, the idiom app/test/import_boundary_test.dart already uses:
52	    // a guard that quietly stops finding its subject is worse than no guard.
53	    if (serverText === null || clientText === null) {
54	      say(
55	        serverText === null ? SERVER_FILE : CLIENT_FILE,
56	        `the cross-tier constants guard cannot read ${serverText === null ? SERVER_FILE : CLIENT_FILE}`,
57	        'restore the file, or point the guard at its new home (the paths live at the top of the pack\'s cross-tier-constants.mjs)',
58	      );
59	      return out;
60	    }
61	
62	    for (const pair of PAIRS) {
63	      const server = serverValue(serverText, pair.server);
64	      const client = clientValue(clientText, pair.client);
65	
66	      if (server === null || client === null) {
67	        say(
68	          server === null ? SERVER_FILE : CLIENT_FILE,
69	          `the guard no longer finds ${server === null ? pair.server : pair.client} in ${server === null ? SERVER_FILE : CLIENT_FILE}`,
70	          'a cross-tier constant was renamed or removed on one side — rename it on both, then update the PAIRS map in the pack check',
71	        );
72	        continue;
73	      }
74	
75	      if (server !== client) {
76	        say(
77	          CLIENT_FILE,
78	          `${pair.client} is ${client} but ${SERVER_FILE}'s ${pair.server} is ${server}`,
79	          `make both copies agree with the docs/DESIGN.md §10 row (the server value is the one delivery actually uses)`,
80	        );
81	        continue;
82	      }
83	
84	      // The doc table is the source both copies transcribe. Only a bare integer
85	      // cell is comparable — the table also carries prose cells ("5 min").
86	      const documented = designValue(designText, pair.server);
87	      if (documented !== null && /^\d+$/.test(documented) && documented !== server) {
88	        say(
89	          DESIGN_FILE,
90	          `§10 documents ${pair.server} as ${documented}, but both tiers carry ${server}`,
91	          'update the §10 row, or the two copies — the table is the single source of truth the copies transcribe',
92	        );
93	      }
94	    }
95	
96	    return out;
97	  },
98	};
99	
100	// `export const NAME = <value>;` — the shape every entry in constants.ts uses.
101	function serverValue(text, name) {
102	  const m = new RegExp(`^export const ${name}\\s*=\\s*([^;]+);`, 'm').exec(text);
103	  return m ? normalize(m[1]) : null;
104	}
105	
106	// `const int name = <value>;` / `const String name = '<value>';` — config.dart's shape.
107	function clientValue(text, name) {
108	  const m = new RegExp(`^const\\s+\\w+\\s+${name}\\s*=\\s*([^;]+);`, 'm').exec(text);
109	  return m ? normalize(m[1]) : null;
110	}
111	
112	// The §10 table row: | `NAME` | value | lives in ... |
113	function designValue(text, name) {
114	  if (text === null) return null;
115	  const m = new RegExp(`^\\|\\s*\`${name}\`\\s*\\|([^|]*)\\|`, 'm').exec(text);
116	  return m ? normalize(m[1]) : null;
117	}
118	
119	// Compare values, not spelling: strip whitespace and one layer of quotes so
120	// 'us-central1' and "us-central1" are the same value.
121	function normalize(raw) {
122	  const v = raw.trim();
123	  const quoted = /^(['"])(.*)\1$/.exec(v);
124	  return quoted ? quoted[2] : v;
125	}
126	
127	export default rule;
128

1	// RULES.md §"One table, two copies": adding a cross-tier constant is a
2	// four-part change — the docs/DESIGN.md §10 row, the server copy, the client
3	// copy, and the `PAIRS` map in cross-tier-constants.mjs. This guard covers the
4	// fourth part: "a value absent from PAIRS is a value nothing is guarding."
5	//
6	// cross-tier-constants compares the pairs that are ALREADY listed; nothing
7	// compares the list against the tiers. So the failure it cannot see is the
8	// quiet one: a new constant copied into both constants.ts and config.dart but
9	// never added to PAIRS compiles, passes every suite, and passes the pack's own
10	// checks — while the two copies are free to drift apart forever, which is the
11	// exact bug cross-tier-constants exists to catch.
12	//
13	// The datum reconciled is "this constant is carried by both tiers", written
14	// down twice: once as a declaration in each tier's constants file, once as an
15	// entry in PAIRS. Like the pack's other guards it dictates no value, shape, or
16	// behaviour — its finding reads "make the copies agree", never "restore this
17	// constant".
18	//
19	// Detection pairs by NAMING CONVENTION across the two files, not by grepping
20	// for a list of names: a server `export const SHOUT_RADIUS_M` is cross-tier
21	// exactly when config.dart declares its lowerCamel counterpart `shoutRadiusM`.
22	// That is why the single-tier constants stay quiet by construction rather than
23	// by exemption — PRESENCE_TTL_MS, SEND_COOLDOWN_MS and the client's heartbeat
24	// cadence have no counterpart to find, so they are never candidates. The known
25	// cost is the reverse: a pair deliberately named against the convention
26	// (REGION / functionsRegion) is invisible to the convention and is only seen
27	// because it is already in PAIRS. That is a miss, never a false alarm — a
28	// finding here is always a real both-tier constant nothing is guarding.
29	//
30	// Dependency-free by design (a local pack's checks must load without the shared
31	// mount): it builds plain finding objects instead of importing the engine helper.
32	
33	const SERVER_FILE = 'firebase/functions/src/constants.ts';
34	const CLIENT_FILE = 'app/lib/config.dart';
35	const GUARD_FILE = '.claudinite/local/packs/shouts-and-whispers/cross-tier-constants.mjs';
36	
37	// `export const NAME = <value>;` — the shape every entry in constants.ts uses.
38	const SERVER_DECL = /^export const ([A-Z][A-Z0-9_]*)\s*=/gm;
39	// `const int name = ...;` / `const Duration name = ...;` — config.dart's shape.
40	const CLIENT_DECL = /^const\s+\w+\s+([a-z]\w*)\s*=/gm;
41	// One `{ server: 'NAME', client: 'name' }` entry of the guard's PAIRS map.
42	const PAIR_ENTRY = /server:\s*'([^']+)'\s*,\s*client:\s*'([^']+)'/g;
43	
44	const rule = {
45	  id: 'shouts-and-whispers/cross-tier-constant-coverage',
46	  severity: 'blocking',
47	  description: 'Every constant both tiers declare is listed in the cross-tier-constants guard\'s PAIRS map',
48	  doc: '.claudinite/local/packs/shouts-and-whispers/RULES.md',
49	  why: 'cross-tier-constants only compares the pairs it is given, so a constant copied into both tiers but never added to PAIRS is guarded by nothing — the two copies drift apart with every test still green, which is the very failure that guard exists to catch',
50	
51	  run(ctx) {
52	    const out = [];
53	    const say = (file, what, fix) => out.push({
54	      rule: rule.id, severity: rule.severity, file, line: null,
55	      what, why: rule.why, fix, doc: rule.doc,
56	    });
57	
58	    const serverText = ctx.read(SERVER_FILE);
59	    const clientText = ctx.read(CLIENT_FILE);
60	    const guardText = ctx.read(GUARD_FILE);
61	
62	    // Staleness guard, the idiom the pack's other checks already use: a guard
63	    // that quietly stops finding its subject is worse than no guard.
64	    const missing = [SERVER_FILE, CLIENT_FILE, GUARD_FILE]
65	      .find((f, i) => [serverText, clientText, guardText][i] === null);
66	    if (missing) {
67	      say(missing,
68	        `the cross-tier constant coverage guard cannot read ${missing}`,
69	        'restore the file, or point the guard at its new home (the paths live at the top of the pack\'s cross-tier-constant-coverage.mjs)');
70	      return out;
71	    }
72	
73	    const listed = new Set(names(guardText, PAIR_ENTRY, 1));
74	    if (!listed.size) {
75	      say(GUARD_FILE,
76	        `no PAIRS entries found in ${GUARD_FILE} — the coverage guard has nothing to compare the tiers against`,
77	        'keep the guarded pairs as literal `{ server: \'NAME\', client: \'name\' }` entries in the PAIRS map, or point this guard at its new home');
78	      return out;
79	    }
80	
81	    const declared = names(serverText, SERVER_DECL, 1);
82	    if (!declared.length) {
83	      say(SERVER_FILE,
84	        `no exported constants found in ${SERVER_FILE} — the coverage guard has nothing to check`,
85	        'keep the server constants as top-level `export const NAME = ...` declarations, or point the guard at its new home');
86	      return out;
87	    }
88	
89	    const onClient = new Set(names(clientText, CLIENT_DECL, 1));
90	
91	    for (const name of declared) {
92	      if (listed.has(name)) continue;
93	      // Cross-tier by construction: the client declares the same constant under
94	      // the lowerCamel spelling of the same name. A server-only constant has no
95	      // counterpart here and is never a candidate.
96	      const counterpart = camel(name);
97	      if (!onClient.has(counterpart)) continue;
98	
99	      say(SERVER_FILE,
100	        `${name} is declared in ${SERVER_FILE} and ${counterpart} in ${CLIENT_FILE}, but the pair is absent from the PAIRS map in ${GUARD_FILE}`,
101	        `add { server: '${name}', client: '${counterpart}' } to PAIRS — a cross-tier constant is a four-part change (the docs/DESIGN.md §10 row, both copies, and the PAIRS entry), and until the pair is listed nothing compares the two copies`);
102	    }
103	
104	    return out;
105	  },
106	};
107	
108	// Every capture-group-1 match of `pattern` in `text`, in source order.
109	function names(text, pattern, group) {
110	  const found = [];
111	  pattern.lastIndex = 0;
112	  let m;
113	  while ((m = pattern.exec(text)) !== null) found.push(m[group]);
114	  return found;
115	}
116	
117	// SHOUT_RADIUS_M -> shoutRadiusM: the spelling convention the two tiers use for
118	// one constant (TypeScript SCREAMING_SNAKE, Dart lowerCamel).
119	function camel(screamingSnake) {
120	  return screamingSnake
121	    .toLowerCase()
122	    .split('_')
123	    .map((part, i) => (i === 0 ? part : part.charAt(0).toUpperCase() + part.slice(1)))
124	    .join('');
125	}
126	
127	export default rule;
128

1	// RULES.md §"Two encoders, one contract": presence geohashes are written by the
2	// Flutter client (app/lib/geo/geohash.dart, hand-rolled) and read back by the
3	// Cloud Function's geohash range queries (geofire-common). The two only meet if
4	// they encode at the SAME precision — a 9-char client hash never falls inside the
5	// bounds of a 10-char server query, so a precision changed on one side alone
6	// makes sendMessage find nobody, silently, with every test still green.
7	//
8	// The precision is a literal at the call sites, so it is a static signature and
9	// converts to a check; that the two ENCODERS agree character-for-character is not
10	// static and stays prose plus the known-vector suites both tiers commit.
11	//
12	// Dependency-free by design (a local pack's checks must load without the shared
13	// mount): it builds plain finding objects instead of importing the engine helper.
14	
15	// `geohash.encode(p.lat, p.lng, precision: 9)` in the Flutter client.
16	const DART_CALL = /\bencode\s*\(([^)]*)precision:\s*(\d+)\s*\)/g;
17	// `geohashForLocation([lat, lng], 9)` in the Cloud Functions source.
18	const TS_CALL = /\bgeohashForLocation\s*\(\s*\[[^\]]*\]\s*,\s*(\d+)\s*\)/g;
19	
20	const DART_ROOT = 'app/lib/';
21	const TS_ROOT = 'firebase/functions/src/';
22	
23	const rule = {
24	  id: 'shouts-and-whispers/geohash-precision-parity',
25	  severity: 'blocking',
26	  description: 'The client heartbeat and the Cloud Functions encode presence geohashes at the same precision',
27	  doc: '.claudinite/local/packs/shouts-and-whispers/RULES.md',
28	  why: 'the server queries presence by geohash range, so a precision that differs from the one the client wrote makes every range query miss its recipients — no error, no failing test, just messages delivered to nobody',
29	
30	  run(ctx) {
31	    const out = [];
32	    const say = (file, line, what, fix) => out.push({
33	      rule: rule.id, severity: rule.severity, file, line,
34	      what, why: rule.why, fix, doc: rule.doc,
35	    });
36	
37	    const client = sites(ctx, (f) => f.startsWith(DART_ROOT) && f.endsWith('.dart'), DART_CALL, 2);
38	    const server = sites(ctx, (f) => f.startsWith(TS_ROOT) && f.endsWith('.ts'), TS_CALL, 1);
39	
40	    // Staleness guard, the idiom app/test/import_boundary_test.dart already uses:
41	    // if either side's call site has moved out of the scanned tree the guard is
42	    // no longer guarding anything, and that must be loud.
43	    if (!client.length || !server.length) {
44	      say(
45	        !client.length ? `${DART_ROOT}geo/geohash.dart` : `${TS_ROOT}index.ts`,
46	        null,
47	        `no explicit geohash precision found under ${!client.length ? DART_ROOT : TS_ROOT} — the parity guard has nothing to compare`,
48	        'keep the precision an explicit literal at the encode call site (never an implicit library default), or point the guard at its new home',
49	      );
50	      return out;
51	    }
52	
53	    const values = [...new Set([...client, ...server].map((s) => s.precision))];
54	    if (values.length > 1) {
55	      const where = [...client, ...server]
56	        .map((s) => `${s.file}:${s.line} → ${s.precision}`)
57	        .join(', ');
58	      for (const site of server) {
59	        say(
60	          site.file, site.line,
61	          `presence geohash precision disagrees across the tiers (${where})`,
62	          'encode at one precision on both sides (DESIGN.md §3 fixes it at 9), and extend the known-vector tests on both tiers to the new precision',
63	        );
64	      }
65	    }
66	
67	    return out;
68	  },
69	};
70	
71	function sites(ctx, matches, pattern, group) {
72	  const found = [];
73	  for (const file of ctx.files.filter(matches)) {
74	    const text = ctx.read(file);
75	    if (text === null) continue;
76	    pattern.lastIndex = 0;
77	    let m;
78	    while ((m = pattern.exec(text)) !== null) {
79	      found.push({
80	        file,
81	        line: text.slice(0, m.index).split('\n').length,
82	        precision: Number(m[group]),
83	      });
84	    }
85	  }
86	  return found;
87	}
88	
89	export default rule;
90

1	// RULES.md §"Two encoders, one contract": the client's hand-rolled encoder
2	// (app/lib/geo/geohash.dart) and the server's geofire-common must produce
3	// IDENTICAL strings, and the only thing standing behind that claim is a pair of
4	// known-vector suites that carry the SAME vectors deliberately —
5	// app/test/geohash_test.dart and firebase/functions/test/geohash-compat.test.ts.
6	//
7	// The claim is only as good as the overlap. Add a vector to one suite and not
8	// the other and both suites still pass, on both tiers, forever: the new
9	// coordinate is asserted against one encoder and nothing compares it to the
10	// other. Nothing in either toolchain can see it — the files are in different
11	// languages, run by different runners, in different CI jobs.
12	//
13	// This is the "extending one vector list means extending the other" half of the
14	// section, and it is a static signature: two committed tables of literals that
15	// must agree, the same shape as this pack's cross-tier-constants guard. It does
16	// NOT check that the encoders agree — that is runtime behaviour, is what the
17	// suites themselves are for, and stays prose.
18	//
19	// Detection parses rather than greps: it reads only the assertions written at
20	// the shared production precision 9 (the client's default-precision `encode`
21	// calls, the server's explicit `geohashForLocation([lat, lng], 9)` calls), so
22	// the deliberately unpaired vectors — the client's precision 1/5/11/12 cases,
23	// the server's 10-char default-precision cases — are not mistaken for drift.
24	//
25	// Dependency-free by design (a local pack's checks must load without the shared
26	// mount): it builds plain finding objects instead of importing the engine helper.
27	
28	const DART_FILE = 'app/test/geohash_test.dart';
29	const TS_FILE = 'firebase/functions/test/geohash-compat.test.ts';
30	
31	// `expect(encode(57.64911, 10.40744), 'u4pruydqq');` — the two-argument form
32	// only, which is precision 9 by default (DESIGN.md §3). A call carrying an
33	// explicit `precision:` has a third argument and is deliberately not matched.
34	const DART_VECTOR =
35	  /expect\(\s*encode\(\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)\s*\)\s*,\s*'([0-9a-z]+)'\s*\)/g;
36	// `expect(geohashForLocation([57.64911, 10.40744], 9)).toBe('u4pruydqq');` — the
37	// explicit precision-9 form only; the default-precision calls encode 10 chars
38	// and have no client counterpart.
39	const TS_VECTOR =
40	  /expect\(\s*geohashForLocation\(\s*\[\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)\s*\]\s*,\s*9\s*\)\s*\)\s*\.toBe\(\s*'([0-9a-z]+)'\s*\)/g;
41	
42	const rule = {
43	  id: 'shouts-and-whispers/geohash-vector-parity',
44	  severity: 'blocking',
45	  description: 'The two tiers\' known-vector geohash suites carry the same precision-9 vectors',
46	  doc: '.claudinite/local/packs/shouts-and-whispers/RULES.md',
47	  why: 'the paired suites are the only evidence that the client\'s hand-rolled encoder and the server\'s geofire-common agree; a vector asserted on one side alone is a coordinate nobody ever compared, and both suites stay green while the compatibility claim quietly stops covering it',
48	
49	  run(ctx) {
50	    const out = [];
51	    const say = (file, line, what, fix) => out.push({
52	      rule: rule.id, severity: rule.severity, file, line,
53	      what, why: rule.why, fix, doc: rule.doc,
54	    });
55	
56	    const dartText = ctx.read(DART_FILE);
57	    const tsText = ctx.read(TS_FILE);
58	
59	    // Staleness guard, the idiom the pack's other checks already use: a guard
60	    // that quietly stops finding its subject is worse than no guard.
61	    if (dartText === null || tsText === null) {
62	      const missing = dartText === null ? DART_FILE : TS_FILE;
63	      say(missing, null,
64	        `the geohash vector parity guard cannot read ${missing}`,
65	        'restore the suite, or point the guard at its new home (the paths live at the top of the pack\'s geohash-vector-parity.mjs)');
66	      return out;
67	    }
68	
69	    const dart = vectors(dartText, DART_VECTOR);
70	    const ts = vectors(tsText, TS_VECTOR);
71	
72	    if (!dart.size || !ts.size) {
73	      const empty = !dart.size ? DART_FILE : TS_FILE;
74	      say(empty, null,
75	        `no precision-9 known vectors found in ${empty} — the parity guard has nothing to compare`,
76	        'keep the shared vectors as literal precision-9 assertions in both suites (the client\'s default-precision `encode`, the server\'s explicit `geohashForLocation([lat, lng], 9)`), or point the guard at its new home');
77	      return out;
78	    }
79	
80	    for (const [coord, near] of pairwise(dart, ts)) {
81	      const other = near.opposite.get(coord);
82	
83	      if (other === undefined) {
84	        const [have, want] = near.side === 'dart' ? [DART_FILE, TS_FILE] : [TS_FILE, DART_FILE];
85	        say(want, null,
86	          `${have} asserts (${coord}) → '${near.hash}' at precision 9, but ${want} carries no precision-9 vector for that coordinate`,
87	          `add the same coordinate to ${want} — the suites are the compatibility contract, so a vector only one tier asserts proves nothing about the other`);
88	        continue;
89	      }
90	
91	      if (other.hash !== near.hash && near.side === 'dart') {
92	        say(TS_FILE, other.line,
93	          `the suites disagree on (${coord}): ${DART_FILE} expects '${near.hash}', ${TS_FILE} expects '${other.hash}'`,
94	          'the two encoders must produce identical strings, so one of these expectations is wrong — recompute the vector and fix the suite that is stale, never loosen one to match the other');
95	      }
96	    }
97	
98	    return out;
99	  },
100	};
101	
102	// coordinate key → { hash, line }, for every vector asserted at precision 9.
103	function vectors(text, pattern) {
104	  const found = new Map();
105	  pattern.lastIndex = 0;
106	  let m;
107	  while ((m = pattern.exec(text)) !== null) {
108	    // Compare coordinates as numbers, not spelling: 0 and 0.0 are one point.
109	    const key = `${Number(m[1])}, ${Number(m[2])}`;
110	    if (!found.has(key)) {
111	      found.set(key, { hash: m[3], line: text.slice(0, m.index).split('\n').length });
112	    }
113	  }
114	  return found;
115	}
